actions.script:
import groovy.json.JsonSlurper

String effectiveGraphId = (graphId ?: 'OtCyberNormGraph').toString()
String effectiveGraphName = (graphName ?: 'OT Cybersecurity Normative Graph').toString()
String effectiveGraphDescription = (graphDescription ?:
        'Normative graph of OT cybersecurity clauses generated from norm PDF sources.').toString()

File verticesFile = new File(verticesFilePath as String)
File edgesFile = new File(edgesFilePath as String)
if (!verticesFile.exists()) throw new IllegalArgumentException("Norm graph vertices file not found: ${verticesFilePath}")
if (!edgesFile.exists()) throw new IllegalArgumentException("Norm graph edges file not found: ${edgesFilePath}")

// vertex-metadata.jsonl / edge-metadata.jsonl live alongside the vertices/edges files,
// as produced by generate_norm_graph.py.
File vertexMetadataFile = new File(verticesFile.parentFile, 'vertex-metadata.jsonl')
File edgeMetadataFile = new File(edgesFile.parentFile, 'edge-metadata.jsonl')

if (Boolean.TRUE.equals(clearExisting)) {
    ec.entity.find('moqui.math.Parameter').condition('graphId', effectiveGraphId).deleteAll()
    ec.entity.find('moqui.math.GraphEdge').condition('graphId', effectiveGraphId).deleteAll()
    ec.entity.find('moqui.math.GraphVertex').condition('graphId', effectiveGraphId).deleteAll()
}

def graphValue = ec.entity.find('moqui.math.Graph').condition('graphId', effectiveGraphId).one()
if (graphValue) graphValue = graphValue.cloneValue()
if (!graphValue) {
    graphValue = ec.entity.makeValue('moqui.math.Graph')
    graphValue.graphId = effectiveGraphId
    graphValue.create()
} else {
    if (!graphValue.name) graphValue.name = effectiveGraphName
    if (!graphValue.description) graphValue.description = effectiveGraphDescription
    graphValue.update()
}

// attribute key -> ParameterDef id, one map for vertices and one for edges (see
// data/CyberNormGraphMetadataSeedData.xml for the full ParameterDef catalog).
Map<String, String> vertexParameterDefByKey = [
        vertexType      : 'CyberNormVertexTypeParam',
        logicalId       : 'CyberNormLogicalIdParam',
        documentId      : 'CyberNormDocumentIdParam',
        documentFamily  : 'CyberNormDocumentFamilyParam',
        documentTitle   : 'CyberNormDocumentTitleParam',
        edition         : 'CyberNormEditionParam',
        clauseNumber    : 'CyberNormClauseNumberParam',
        clauseTitle     : 'CyberNormClauseTitleParam',
        clauseText      : 'CyberNormClauseTextParam',
        sourceFile      : 'CyberNormSourceFileParam',
        page            : 'CyberNormPageParam',
        provenanceClass : 'CyberNormProvenanceClassParam'
]
Map<String, String> edgeParameterDefByKey = [
        provenanceClass : 'CyberNormProvenanceClassParam',
        confidence      : 'CyberNormConfidenceParam',
        rationale       : 'CyberNormRationaleParam'
]

Closure<Void> storeParameter = { String parameterDefId, Object rawValue, String graphVertexId, String graphEdgeId ->
    if (rawValue == null) return
    String textValue = rawValue.toString()
    if (!textValue) return
    String source = "${effectiveGraphId}|${graphVertexId ?: ''}|${graphEdgeId ?: ''}|${parameterDefId}"
    String parameterId = java.security.MessageDigest.getInstance('SHA-1').digest(source.getBytes('UTF-8')).encodeHex().toString()
    def parameterValue = ec.entity.find('moqui.math.Parameter').condition('parameterId', parameterId).one()
    boolean isNew = parameterValue == null
    if (isNew) {
        parameterValue = ec.entity.makeValue('moqui.math.Parameter')
        parameterValue.parameterId = parameterId
    } else {
        parameterValue = parameterValue.cloneValue()
    }
    parameterValue.parameterDefId = parameterDefId
    parameterValue.graphId = effectiveGraphId
    parameterValue.graphVertexId = graphVertexId
    parameterValue.graphEdgeId = graphEdgeId
    parameterValue.textValue = textValue
    if (isNew) parameterValue.create() else parameterValue.update()
}

JsonSlurper slurper = new JsonSlurper()
loadedVertexCount = 0
loadedEdgeCount = 0

verticesFile.eachLine('UTF-8') { String line ->
    String trimmed = line?.trim()
    if (!trimmed) return
    Map row = slurper.parseText(trimmed) as Map
    def vertexValue = ec.entity.find('moqui.math.GraphVertex')
            .condition('graphId', row.graphId)
            .condition('graphVertexId', row.graphVertexId)
            .one()
    boolean isNew = vertexValue == null
    if (isNew) {
        vertexValue = ec.entity.makeValue('moqui.math.GraphVertex')
        vertexValue.graphId = row.graphId
        vertexValue.graphVertexId = row.graphVertexId
    } else {
        vertexValue = vertexValue.cloneValue()
    }
    // GraphVertex.label is VARCHAR(63); truncate here (not in the Python
    // generator) so the JSONL/graph.json exports keep the full label for
    // debugging, same convention as moqui-mcp's load#ArtifactGraph normalizeLabel.
    String rawLabel = (row.label ?: '').toString()
    vertexValue.label = rawLabel.length() > 63 ? (rawLabel.substring(0, 60) + '...') : rawLabel
    vertexValue.notBelongToEdge = row.notBelongToEdge ?: 'N'
    if (isNew) vertexValue.create() else vertexValue.update()
    loadedVertexCount++
}

if (vertexMetadataFile.exists()) {
    vertexMetadataFile.eachLine('UTF-8') { String line ->
        String trimmed = line?.trim()
        if (!trimmed) return
        Map row = slurper.parseText(trimmed) as Map
        Map attributes = (row.attributes ?: [:]) as Map
        attributes.each { key, value ->
            String parameterDefId = vertexParameterDefByKey[key as String]
            if (parameterDefId) storeParameter(parameterDefId, value, row.graphVertexId as String, null)
        }
    }
}

edgesFile.eachLine('UTF-8') { String line ->
    String trimmed = line?.trim()
    if (!trimmed) return
    Map row = slurper.parseText(trimmed) as Map
    def edgeValue = ec.entity.find('moqui.math.GraphEdge')
            .condition('graphId', row.graphId)
            .condition('graphEdgeId', row.graphEdgeId)
            .one()
    boolean isNew = edgeValue == null
    if (isNew) {
        edgeValue = ec.entity.makeValue('moqui.math.GraphEdge')
        edgeValue.graphId = row.graphId
        edgeValue.graphEdgeId = row.graphEdgeId
    } else {
        edgeValue = edgeValue.cloneValue()
    }
    edgeValue.edgeTypeEnumId = row.edgeTypeEnumId
    edgeValue.fromVertexId = row.fromVertexId
    edgeValue.toVertexId = row.toVertexId
    edgeValue.isDirected = row.isDirected ?: 'Y'
    edgeValue.isLoop = row.isLoop ?: 'N'
    edgeValue.label = row.label
    if (isNew) edgeValue.create() else edgeValue.update()
    loadedEdgeCount++
}

if (edgeMetadataFile.exists()) {
    edgeMetadataFile.eachLine('UTF-8') { String line ->
        String trimmed = line?.trim()
        if (!trimmed) return
        Map row = slurper.parseText(trimmed) as Map
        Map attributes = (row.attributes ?: [:]) as Map
        attributes.each { key, value ->
            String parameterDefId = edgeParameterDefByKey[key as String]
            if (parameterDefId) storeParameter(parameterDefId, value, null, row.graphEdgeId as String)
        }
    }
}

String effectiveGraphId = (graphId ?: 'OtCyberNormGraph').toString()

Closure<Map> resolveVertex = { String vertexId ->
    def meta = ec.entity.find('moqui.cyber.graph.CyberNormVertexMeta')
            .condition('graphVertexId', vertexId).one()
    [graphVertexId: vertexId, documentId: meta?.documentId,
            clauseNumber: meta?.clauseNumber, clauseTitle: meta?.clauseTitle]
}

// CyberNormEdgeMeta (the view-entity) is unusable here: its "relationType" alias is a
// name-alias (not a field= remap), which Moqui's EntityFind.condition() rejects
// ("Field relationType not found on entity..., cannot add condition") AND which
// EntityFind.selectFields() also rejects the same way ("not a valid field name") -
// both confirmed by direct testing, not assumed. Separately, even a plain .list() with
// no field restriction triggers a genuine Moqui view-entity bug: FGV (the from-vertex
// GraphVertex join, used only for the view's fromLabel alias) ends up referenced in the
// generated SELECT but silently dropped from the FROM/JOIN clause (self-join of the
// same target entity, GraphVertex, under two different aliases FGV/TGV), causing
// "Column FGV.LABEL not found". Working around this by never touching the view-entity
// for this query - fetching plain moqui.math.GraphEdge rows directly instead (no join,
// "label" is a real field, no alias problem), then resolving confidence via a direct
// moqui.math.Parameter lookup per edge (small counts - a handful of edges per clause,
// not worth a join).
List relationTypes = ['REFERENCES', 'HARMONIZES_WITH']
Closure<String> resolveConfidence = { String edgeId ->
    ec.entity.find('moqui.math.Parameter')
            .condition('graphId', effectiveGraphId)
            .condition('graphEdgeId', edgeId)
            .condition('parameterDefId', 'CyberNormConfidenceParam')
            .one()?.textValue
}
List edgesOut = ec.entity.find('moqui.math.GraphEdge')
        .condition('graphId', effectiveGraphId)
        .condition('fromVertexId', graphVertexId)
        .condition('label', 'in', relationTypes)
        .list()
List edgesIn = ec.entity.find('moqui.math.GraphEdge')
        .condition('graphId', effectiveGraphId)
        .condition('toVertexId', graphVertexId)
        .condition('label', 'in', relationTypes)
        .list()

references = []
edgesOut.each { e ->
    references << [direction: 'outgoing', relationType: e.label,
            confidence: resolveConfidence(e.graphEdgeId as String), clause: resolveVertex(e.toVertexId as String)]
}
edgesIn.each { e ->
    references << [direction: 'incoming', relationType: e.label,
            confidence: resolveConfidence(e.graphEdgeId as String), clause: resolveVertex(e.fromVertexId as String)]
}

import org.moqui.agent.search.ElasticBackendAdapter
import groovy.json.JsonSlurper

def clausesFind = ec.entity.find('moqui.cyber.graph.CyberNormVertexMeta')
        .condition('vertexType', 'NormClause')
        .orderBy('clauseNumber')
if (documentId) clausesFind = clausesFind.condition('documentId', documentId)
List clauses = clausesFind.list()
if (limit) clauses = clauses.take(limit as int)

String effectiveIndex = (indexName ?: 'moqui_cyber_norms_v1').toString()
def adapter = new ElasticBackendAdapter(ec)
if (Boolean.TRUE.equals(forceReindex) && adapter.indexExists(effectiveIndex)) {
    adapter.deleteIndex(effectiveIndex)
}
if (!adapter.indexExists(effectiveIndex)) {
    File mappingFile = new File(ec.factory.getRuntimePath() + '/component/moqui-cybersecurity-agent/tools/norm-indexer/opensearch-mapping-cyber-norms.json')
    Map mappingSpec = new JsonSlurper().parseText(mappingFile.text) as Map
    adapter.createIndex(effectiveIndex, mappingSpec)
}

indexedCount = 0
failedCount = 0
List<Map> batch = []
int batchSize = 50

Closure flushBatch = {
    if (!batch) return
    try {
        adapter.bulkIndex(effectiveIndex, batch)
        indexedCount += batch.size()
    } catch (Throwable t) {
        failedCount += batch.size()
        ec.logger.error("Failed to bulk index ${batch.size()} norm clause documents", t)
    }
    batch = []
}

clauses.each { row ->
    try {
        // get#QueryEmbedding rejects '<'/'>' (HTML-safety validation on its queryText
        // parameter), which real standard clauses legitimately contain (e.g. "< 5",
        // inequality/range text). Strip them before embedding; this only affects what
        // gets embedded, not the stored clauseText.
        String textToEmbed = ((row.clauseText ?: row.clauseTitle ?: row.clauseNumber) as String)
                .replaceAll(/[<>]/, ' ')
        // Isolate each embedding-cache lookup in its own transaction: get#QueryEmbedding
        // writes to ArtifactQueryEmbeddingCache, and a single collision/error there (e.g.
        // two clauses in different documents sharing byte-identical boilerplate text and
        // the same cache key) would otherwise mark the whole batch's transaction
        // rollback-only, cascading failure to every remaining clause.
        Map embeddingResult = ec.service.sync().name('org.moqui.agent.AgentDocumentServices.get#QueryEmbedding')
                .parameters([queryText: textToEmbed])
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) ec.message.clearErrors()
        if (!embeddingResult?.embedding) throw new IllegalStateException("Empty embedding result")
        batch.add([
            doc_id        : row.graphVertexId,
            graphVertexId : row.graphVertexId,
            logicalId     : row.logicalId,
            documentId    : row.documentId,
            documentFamily: row.documentFamily,
            documentTitle : row.documentTitle,
            edition       : row.edition,
            clauseNumber  : row.clauseNumber,
            clauseTitle   : row.clauseTitle,
            clauseText    : row.clauseText,
            sourceFile    : row.sourceFile,
            provenanceClass: row.provenanceClass,
            embedding     : embeddingResult.embedding
        ])
        if (batch.size() >= batchSize) flushBatch()
    } catch (Throwable t) {
        failedCount++
        ec.logger.error("Failed to embed/index norm clause ${row.graphVertexId}", t)
        if (ec.message.hasError()) ec.message.clearErrors()
    }
}
flushBatch()
